class DebugTests(unittest.TestCase):

    def exercise(self, info, method, hot=False):
        entered = threading.Event()
        release = threading.Event()
        other = threading.Event()
        calls = []
        cache = LRUCache(128)
        cond = threading.Condition()
        errors = []

        def body(key):
            calls.append(key)
            if key == 'held':
                entered.set()
                release.wait(4)
            if key == 'other':
                other.set()
            return key
        if method:

            class Owner:

                def __init__(self):
                    self.cache = cache
                    self.cond = cond

                @cachedmethod(lambda self: self.cache, condition=lambda self: self.cond, info=info)
                def run(self, key):
                    return body(key)
            f = Owner().run
        else:
            f = cached(cache, condition=cond, info=info)(body)
        if hot:
            f('other')
            other.clear()

        def call(key):
            try:
                f(key)
            except Exception as e:
                errors.append(repr(e))
        first = threading.Thread(target=call, args=('held',))
        second = threading.Thread(target=call, args=('other',))
        try:
            first.start()
            self.assertTrue(entered.wait(2))
            second.start()
            if hot:
                second.join(1)
                self.assertFalse(second.is_alive(), 'cached unrelated key blocked although no eviction occurs')
            else:
                self.assertTrue(other.wait(1), 'unrelated cache miss blocked although no eviction occurs')
        finally:
            release.set()
            first.join(5)
            second.join(5)
        self.assertFalse(errors, errors)
        self.assertFalse(first.is_alive() or second.is_alive())
        self.assertEqual(calls.count('held'), 1)

    def test_independent_keys_and_cached_hits(self):
