                def __init__(self, cache, cond):
                    self.cache = cache
                    self.cond = cond

                @cachedmethod(
                    lambda self: self.cache,
                    condition=lambda self: self.cond,
                    info=info,
                )
                def run(self, key):
                    return body(key)

